insert into public.interactive_assignment_templates(slug,day,title,target_slugs,is_lab) values ('day-8-foundation-kinematics',8,'Day 8 · Foundation: Constant acceleration problem-solving',array['u1.pick-equation-of-motion'],false);
insert into public.daily_lesson_templates(key,foundation_slug,review_slug,foundation_questions,review_questions,quiz) values ('unit-1-day-8','day-8-foundation-kinematics','day-8-kinematics-problems',array['f8-equation','f8-retrieval','f8-select','f8-braking','f8-position','f8-train','f8-vertical','f8-reversal','f8-exit-stop','f8-exit-position'],array['r2-1a','r2-1b','r2-1c','r2-2a','r2-2b','r2-2c','r2-3a','r2-3b','r2-3c','r2-4a','r2-4b','r2-5a','r2-5b'],'{"title":"Day 8 · Quiz: Constant acceleration problem-solving","instructions":"Work independently after submitting the foundation and review. Choose a positive direction, list givens and unknowns, show units and justify your equation choices. Your teacher releases the quiz grade and reviews mastery separately.","questions":[{"kind":"choice","prompt":"You know v₀, a and elapsed time t for constant acceleration and need displacement. Which equation gives it directly?","options":["Δx = v₀t + ½at²","v = v₀ + at","a = v/t for every initial velocity","x = v₀ + a"],"correct_index":0,"guide":"The displacement equation directly connects the three givens with Δx.","points":1,"demand":{"blooms":"Understand","dok":1,"evidence":"Selects an equation from known and requested quantities."}},{"kind":"choice","prompt":"An upward-thrown ball is at its highest point. Ignoring air resistance and choosing up as positive, which pair applies?","options":["v = 0 and a = 0","v is positive and a = 0","v = 0 and a = −9.8 m/s²","v = −9.8 m/s and a = 0"],"correct_index":2,"guide":"Vertical velocity is momentarily zero; gravitational acceleration remains downward.","points":1,"demand":{"blooms":"Understand","dok":1,"evidence":"Identifies the implicit zero without eliminating gravity."}},{"kind":"choice","prompt":"A car brakes from +18 m/s to rest at constant −3 m/s². What is its braking displacement?","options":["−54 m","+54 m","+6 m","+108 m"],"correct_index":1,"guide":"Δx = (0−18²)/(2×−3) = +54 m. The car keeps moving positively until it stops.","points":1,"demand":{"blooms":"Apply","dok":2,"evidence":"Selects and uses a no-time equation with signed braking quantities."}},{"kind":"choice","prompt":"A cart starts at x₀ = −7 m and has displacement +10 m. What is its final position?","options":["+17 m","+10 m","−17 m","+3 m"],"correct_index":3,"guide":"x = x₀ + Δx = −7 + 10 = +3 m.","points":1,"demand":{"blooms":"Apply","dok":1,"evidence":"Distinguishes a coordinate from a change in coordinate."}},{"kind":"written","prompt":"A train starts from rest and accelerates uniformly at +0.80 m/s² until it reaches +16 m/s. Choose equations to find the time and displacement. Justify both choices, check the displacement using average velocity and explain why final velocity times time would give the wrong result.","guide":"t = (16−0)/0.80 = 20 s. Δx = ½×0.80×20² = 160 m. The velocity equation connects the given velocities/acceleration to time; the displacement equation uses that time. Average velocity is (0+16)/2 = 8 m/s, giving 160 m. Final velocity×time gives 320 m and incorrectly assumes the final speed throughout. Constant acceleration makes the endpoint average valid.","points":3,"demand":{"blooms":"Analyze","dok":2,"evidence":"Justifies connected equation choices and validates displacement through a second method."}},{"kind":"written","prompt":"A cart starts at x₀ = +4 m with v₀ = +3 m/s and constant a = −3 m/s² for 2 s. One student says it traveled no distance because its displacement is zero; another reports final position as zero. Evaluate both claims. Use a turning-point calculation and a velocity–time graph to defend the correct displacement, distance and final position.","guide":"Δx = 3×2 + ½×(−3)×2² = 0 m; x = +4 m. It stops/reverses at 1 s, after displacement +1.5 m (position 5.5 m), and returns 1.5 m, for distance 3 m. A straight v–t line from +3 to −3 has equal positive/negative areas: signed sum zero, absolute sum 3 m. Both claims confuse endpoint change with either path length or final coordinate. Award for correct quantities, turning-point evidence and a graph-based critique.","points":3,"demand":{"blooms":"Evaluate","dok":3,"evidence":"Evaluates competing interpretations using a turning point, signed graph areas and an initial coordinate."}}]}'::jsonb);
